 1	import java.util.Objects;
 2	
 3	public final class LongestCommonSubsequence {
 4	    private LongestCommonSubsequence() {
 5	    }
 6	
 7	    public static int lcs(String first, String second) {
 8	        Objects.requireNonNull(first, "first must not be null");
 9	        Objects.requireNonNull(second, "second must not be null");
10	
11	        if (first.isEmpty() || second.isEmpty()) {
12	            return 0;
13	        }
14	
15	        if (first.equals(second)) {
16	            return first.length();
17	        }
18	
19	        return new Solver(first, second).solve();
20	    }
21	    private static final class Solver {
22	        private final char[] longer;
23	        private final char[] shorter;
24	        private final int[] lengths;
25	
26	        private Solver(String first, String second) {
27	            char[] firstChars = first.toCharArray();
28	            char[] secondChars = second.toCharArray();
29	
30	            if (firstChars.length >= secondChars.length) {
31	                this.longer = firstChars;
32	                this.shorter = secondChars;
33	            } else {
34	                this.longer = secondChars;
35	                this.shorter = firstChars;
36	            }
37	
38	            this.lengths = new int[this.shorter.length + 1];
39	        }
40	
41	        private int solve() {
42	            for (char current : longer) {
43	                updateLengths(current);
44	            }
45	
46	            return lengths[shorter.length];
47	        }
48	
49	        private void updateLengths(char current) {
50	            int diagonal = 0;
51	
52	            for (int j = 1; j <= shorter.length; j++) {
53	                int previousRow = lengths[j];
54	
55	                lengths[j] = current == shorter[j - 1]
56	                    ? diagonal + 1
57	                    : Math.max(lengths[j], lengths[j - 1]);
58	                diagonal = previousRow;
59	            }
60	        }
61	    }
62	}

